declare(strict_types=1);require __DIR__.'/_init.php';if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['ok'=>false,'error'=>'method_not_allowed'],405);$d=json_input();$username=trim((string)($d['username']??''));$email=normalize_email((string)($d['email']??''));$password=(string)($d['password']??'');$display=trim((string)($d['display_name']??''));$device=trim((string)($d['device_name']??''));if(!valid_username($username))json_response(['ok'=>false,'error'=>'invalid_username'],422);if(!filter_var($email,FILTER_VALIDATE_EMAIL))json_response(['ok'=>false,'error'=>'invalid_email'],422);if(strlen($password)<10)json_response(['ok'=>false,'error'=>'weak_password'],422);$pdo=db();$q=$pdo->prepare('SELECT id FROM users WHERE username=? OR email=? LIMIT 1');$q->execute([$username,$email]);if($q->fetch())json_response(['ok'=>false,'error'=>'account_exists'],409);$q=$pdo->prepare("INSERT INTO users(username,email,display_name,password_hash,role,is_active,created_at,updated_at) VALUES(?,?,?,?,'user',1,NOW(),NOW())");$q->execute([$username,$email,$display?:$username,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$token=issue_api_token($id,$device);json_response(['ok'=>true,'token'=>$token,'user'=>['id'=>$id,'username'=>$username,'email'=>$email]],201);
